function patrimonioPrefixo(nome = '') {
  const ignorar = new Set(['DE', 'DA', 'DO', 'DAS', 'DOS', 'E']);
  const palavras = String(nome || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .filter((p) => !ignorar.has(p));
  return palavras.map((p) => p[0]).join('').slice(0, 8) || 'PAT';
}

